perf.naive:
def can_reach_end(jumps: list[int]) -> bool:
    reach = [False] * len(jumps)
    reach[0] = True
    for i in range(len(jumps)):
        if reach[i]:
            for j in range(i + 1, min(len(jumps), i + jumps[i] + 1)):
                reach[j] = True
    return reach[-1]
